<template>
<admin-layout><Head :title="$t(&quot;UMI 历史对账与规则核查&quot;)"/>
 <main class="umi-account">
  <div class="umi-account-heading"><div><span class="umi-eyebrow">UMI / ACCOUNT REVIEW</span><h1>{{ $t("历史对账与规则核查") }}</h1><p>{{ $t("逐项核对原额度、资产和收益构成，保留原关系与历史差异。") }}</p></div><a :href="route('admin.umi')" class="umi-quiet-link">{{ $t("返回账户管理 ↗") }}</a></div>
  <div class="umi-history-note">{{ $t("核查不会增加余额、补发收益或更改原档案。计算一致只说明这些历史字段能对上，不代表完整结算规则或链上储备已经验证。") }}</div>
  <section class="umi-stat-grid"><article><span>{{ $t("核查账户") }}</span><strong>{{report.accounts}}</strong><small>{{report.summary_accounts}} {{ $t("人有完整 CSV 拆分") }}</small></article><article><span>{{ $t("核对一致") }}</span><strong>{{report.counts.matched}}</strong><small>{{ $t("项字段或记录检查") }}</small></article><article><span>{{ $t("待解释差异") }}</span><strong>{{report.counts.difference}}</strong><small>{{ $t("保留原值，不自动修正") }}</small></article><article><span>{{ $t("缺失或异常") }}</span><strong>{{report.counts.missing + report.counts.invalid + report.counts.ambiguous}}</strong><small>{{ $t("资料缺失、校验失败或对应不唯一") }}</small></article></section>
  <section class="umi-panel"><h2>{{ $t("核查明细") }}</h2>
   <form class="umi-review-filters" @submit.prevent="search"><div><label for="umi-audit-uid">{{ $t("原 UID") }}</label><input id="umi-audit-uid" v-model="legacyId" type="number" min="1" :placeholder="$t(&quot;全部已保存账户&quot;)"/></div><div><label for="umi-audit-state">{{ $t("核查结果") }}</label><themed-select id="umi-audit-state" v-model="state"><option value="issues">{{ $t("待核对项目") }}</option><option value="all">{{ $t("全部结果") }}</option><option value="matched">{{ $t("一致") }}</option><option value="difference">{{ $t("有差异") }}</option><option value="missing">{{ $t("缺少资料") }}</option><option value="invalid">{{ $t("校验异常") }}</option><option value="ambiguous">{{ $t("对应不唯一") }}</option><option value="notice">{{ $t("保留说明") }}</option></themed-select></div><button class="umi-action">{{ $t("查询") }}</button><a class="umi-quiet-link" :href="downloadUrl">{{ $t("下载完整核查结果 ↓") }}</a></form>
   <p v-for="(error,key) in $page.props.errors" :key="key" class="umi-error">{{error}}</p>
