 </main>
</admin-layout>
</template>
<script>
import { legacyText } from '@/Functions/LegacyTranslation';

import AdminLayout from '@/Layouts/AdminLayout';import '../../Umi/umi-account.scss';
export default {components:{AdminLayout},props:{runtime:Object,report:Object,evidence:Object,checks:Object,filters:Object},data(){return {legacyId:this.filters.legacy_id||'',state:this.filters.state};},computed:{downloadUrl(){return this.route('admin.umi.reconciliation')+'?'+new URLSearchParams({...(this.filters.legacy_id?{legacy_id:this.filters.legacy_id}:{}),format:'json'});}},methods:{search(){this.$inertia.get(this.route('admin.umi.reconciliation'),{...(this.legacyId?{legacy_id:this.legacyId}:{}),state:this.state});},pageUrl(page){return this.route('admin.umi.reconciliation')+'?'+new URLSearchParams({...this.filters,legacy_id:this.filters.legacy_id||'',page});},stateName(v){return {matched:legacyText("一致"),difference:legacyText("有差异"),missing:legacyText("缺少资料"),invalid:legacyText("校验异常"),ambiguous:legacyText("对应不唯一"),notice:legacyText("保留说明")}[v]||v;},ruleName(v){return {preserved:legacyText("原样保留"),historical_verified:legacyText("历史字段可复算"),incomplete:legacyText("规则待补齐"),conflicting:legacyText("历史费率存在差异"),sample_reconstructed:legacyText("样本已复算"),client_verified:legacyText("客户端规则可确认"),unidentifiable:legacyText("现有证据无法唯一恢复")}[v]||v;},sourceName(id){return (this.evidence.sources.find(s=>s.id===id)||{}).label||id;}}};
</script>
